/**
 * Represents an interface that describes the Scheduler groups.
 */
export interface Group {
    /**
     * Defines the array of resource names to group.
     */
    resources: string[];
    /**
     * Specifies the orientation of the groups.
     */
    orientation: 'horizontal' | 'vertical';
}
